<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';require_admin();$rows=$pdo->query('SELECT b.*,u.name customer_name,u.email,p.package_name,d.destination_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN packages p ON p.id=b.package_id JOIN destinations d ON d.id=p.destination_id ORDER BY b.created_at DESC')->fetchAll();json_out(['bookings'=>$rows]);
